static int binarySearch(int[] a, int key) {
    int lo = 0, hi = a.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] == key) return mid;
        else if (a[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}
Trace (key = 42):
lo = 0, hi = 6, mid = 3 → a[3] = 21 < 42 → lo = 4
lo = 4, hi = 6, mid = 5 → a[5] = 42 → found, return 5.
